function checkPrime(arr) {
  // Loop through each number in the array
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];
    // Check if the number is greater than 1 (primes are greater than 1)
    if (num > 1) {
      // Check if the number is prime
      let isPrime = true;
      for (let j = 2; j <= Math.sqrt(num); j++) {
        if (num % j === 0) {
          isPrime = false;
          break;
        }
      }
      // If the number is prime, log it to the console
      if (isPrime) {
        console.log(num);
        return; // Exit the function if a prime number is found
      }
    }
  }
}

// Example usage
