export var gravity := 9.81 setget set_gravity
export var jump_speed := -10.0 setget set_jump_speed
export var mouse_sensitivity := 0.2 setget set_mouse_sensitivity

var velocity := Vector3.ZERO
var direction := Vector3.ZERO
var is_jumping := false

func _ready():
    $Camera.make_current()

func _input(event):
    if event is InputEventMouseMotion:
        $Camera.rotate_x(-event.relative.y * mouse_sensitivity)
        $Camera.rotate_y(event.relative.x * mouse_sensitivity)

func _physics_process(delta):
    direction = Vector3.ZERO

    if Input.is_action_pressed("move_forward"):
        direction -= transform.basis.z
    if Input.is_action_pressed("move_backward"):
        direction += transform.basis.z
    if Input.is_action_pressed("move_left"):
